const out = src.map((item) => {
  const line = item.line;
  const masked = item.masked;
  let translated;
  if (Object.prototype.hasOwnProperty.call(full, line)) {
    translated = full[line];
  } else if (masked.startsWith("- ")) {
    const idx = masked.lastIndexOf(" - ");
    const head = masked.slice(0, idx + 3);
    const tail = t[line];
    translated = tail === undefined ? masked : head + tail;
  } else {
    translated = masked;
  }
  return { line, translated };
});
out.sort((a, b) => a.line - b.line);
